                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(comp)

    # The large single-color-1 component is the shape to repeat.
    template = max(
        ([(r, c) for r, c in comp if grid[r][c] == 1] for comp in components),
        key=len
    )
    top0 = min(r for r, c in template)
    left0 = min(c for r, c in template)
    bottom0 = max(r for r, c in template)
    right0 = max(c for r, c in template)
    shape = {(r - top0, c - left0) for r, c in template}
    shape_h = bottom0 - top0 + 1

    # The multicolor rectangular component gives the order of colors.
    strip = None
    for comp in components:
        if len({grid[r][c] for r, c in comp}) <= 1:
            continue
        rmin, rmax = min(r for r, c in comp), max(r for r, c in comp)
        cmin, cmax = min(c for r, c in comp), max(c for r, c in comp)
        if len(comp) == (rmax - rmin + 1) * (cmax - cmin + 1):
            strip = (rmin, rmax, cmin, cmax)
            break

    rmin, rmax, cmin, cmax = strip
    if cmax - cmin + 1 >= rmax - rmin + 1:
        colors = [grid[rmin][c] for c in range(cmin, cmax + 1)]
    else:
        colors = [grid[r][cmin] for r in range(rmin, rmax + 1)]

    anchor = colors.index(1)
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        new_top = top0 + (i - anchor) * shape_h
        for dr, dc in shape:
            rr, cc = new_top + dr, left0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
